from iapws import IAPWS97 as W
import math, itertools
T0=W(P=0.0087,x=0).T
Tsh,Tsc=565.0,290.0
def comp(Pm,Tm,Prh,Trh,Tfw,n=120):
    m=W(P=Pm,T=Tm+273.15); fw=W(P=Pm,T=Tfw+273.15)
    hpo=W(P=Prh,s=m.s); rh=W(P=Prh,T=Trh+273.15)
    Q=(m.h-fw.h)+(rh.h-hpo.h); dS=(m.s-fw.s)+(rh.s-hpo.s)
    # cold composite: at each temperature level T, cumulative heat absorbed below T
    def h_at(P,T): 
        return W(P=P,T=T+273.15).h
    Tlist=sorted(set([Tfw+ (Tm-Tfw)*i/n for i in range(n+1)]+[hpo.T-273.15+(Trh-(hpo.T-273.15))*i/n for i in range(n+1)]))
    try:
        Ts=W(P=Pm,x=0).T-273.15; hl=W(P=Pm,x=0).h; hv=W(P=Pm,x=1).h; sub=True
    except Exception: sub=False
    def Qbelow(T):
        q=0
        # main stream
        if T<=Tfw: pass
        else:
            Tc=min(T,Tm)
            if sub and abs(Tc-Ts)<1e-9: hc=hl
            elif sub and Tc>Ts: hc=h_at(Pm,Tc)
            elif sub and Tc<Ts: hc=h_at(Pm,Tc)
            else: hc=h_at(Pm,Tc)
            q+=hc-fw.h
        Tr0=hpo.T-273.15
        if T>Tr0:
            q+=h_at(Prh,min(T,Trh))-hpo.h
        return q
    mind=1e9; where=None
    pts=Tlist+([Ts-1e-6,Ts+1e-6] if sub else [])
    for T in pts:
        if T<Tfw: continue
        qb=Qbelow(T)
        if sub and T>=Ts: pass
        # include latent: if T just above Ts add evaporation (h_at gives vapor above Ts)
        Tsalt=Tsc+(Tsh-Tsc)*qb/Q
        d=Tsalt-T
        if d<mind: mind=d; where=T
    # also check at bubble point (salt temp when only sensible below Ts absorbed)
    if sub:
        qb=(hl-fw.h)+((h_at(Prh,min(Ts,Trh))-hpo.h) if Ts>hpo.T-273.15 else 0)
        d=Tsc+(Tsh-Tsc)*qb/Q-Ts
        if d<mind: mind=d; where=Ts
    return 1-T0*dS/Q, mind, where, Q, dS
if __name__=="__main__":
    for a in [(12.6,550,2.2,550,245),(12.6,550,2.2,550,260),(16.5,550,3.5,550,260),(10.0,540,2.0,540,240)]:
        e,d,w,Q,dS=comp(*a); print(a,f"eta={e:.4f} minDT={d:.2f} at T={w:.1f}")
    best={}
    for Pm in [10,12.6,14,16.5,20,24,26,30]:
      for Prh in [1.5,2,2.5,3,3.5,4,5,6]:
        if Prh>=Pm/2: continue
        for Tfw in range(200,291,5):
          try: e,d,w,Q,dS=comp(Pm,550,Prh,550,Tfw,n=60)
          except Exception as ex: continue
          for lim in (0,10):
            if d>=lim and (lim not in best or e>best[lim][0]): best[lim]=(e,Pm,Prh,Tfw,d)
    print(best)
